import { Component, computed, inject, input, model, signal, TemplateRef } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { Router } from '@angular/router';
import { NzDrawerModule } from 'ng-zorro-antd/drawer';
import { NzModalModule } from 'ng-zorro-antd/modal';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import {
  TablerIconComponent, IconArrowsDiagonal, IconLayout, IconX, IconCheck,
  IconLayoutSidebarRight, IconAppWindow, IconMaximize, IconExternalLink, IconLayoutColumns,
} from '@tabler/icons-angular';

/** 5 surface hiển thị chi tiết (như Notion: Master/Side/Center/Full/New tab).
 *  master = panel GẮN CỐ ĐỊNH bên phải danh sách (bảng trái · chi tiết phải, không che). */
export type HrmPeekMode = 'master' | 'side' | 'center' | 'full' | 'tab';

/** hrm-detail-peek — hộp chi tiết đa-surface. Cùng 1 nội dung ([content] template),
 *  đổi cách hiển thị: side (drawer phải, không mask → danh sách vẫn thao tác),
 *  center (modal giữa), full (điều hướng route), tab (mở tab browser mới).
 *  Header có bộ switch mode kiểu Notion. Toàn token → tự Light/Dark.
 *
 *  <hrm-detail-peek [(open)]="show" [(peekMode)]="mode" [title]="name" [content]="detailTpl"
 *     [routeUrl]="'/emp/'+id" [modeLabels]="labels" />
 *  <ng-template #detailTpl> ...nội dung chi tiết... </ng-template>
 *
 *  full + tab CẦN [routeUrl] (route hiển thị bản ghi độc lập, chia sẻ link được). */
@Component({
  selector: 'hrm-detail-peek',
  imports: [NgTemplateOutlet, NzDrawerModule, NzModalModule, NzDropDownModule, NzMenuModule, TablerIconComponent],
  template: `
    <!-- MASTER: panel inline cố định bên phải danh sách (đặt component NGAY SAU danh sách
         trong 1 hàng flex — bảng trái, chi tiết phải, không che nội dung). -->
    @if (open() && peekMode() === 'master') {
      <aside class="dp-master" [class.dp-resizing]="resizing()" [style.width.px]="masterW()">
        <!-- Tay kéo đổi độ rộng (mép trái) — có grip để user nhận biết kéo được. -->
        <div class="dp-resize" role="separator" aria-orientation="vertical" [attr.aria-label]="resizeLabel() || null"
          (pointerdown)="startResize($event, 'master')"><span class="dp-grip"></span></div>
        <div class="dp-mhead"><ng-container [ngTemplateOutlet]="peekHead" /></div>
        <div class="dp-mbody"><ng-container [ngTemplateOutlet]="bodyTpl()" [ngTemplateOutletContext]="{ $implicit: peekMode() }" /></div>
        <!-- FOOTER ghim đáy (fix cố định) — cụm hành động; đồng bộ với drawer/modal. -->
        @if (footer()) {
          <div class="dp-mfoot"><ng-container [ngTemplateOutlet]="footer()!" /></div>
        }
      </aside>
    }

    <!-- Anchor drawer/modal — GIẤU khỏi layout (display:none): nội dung render qua CDK overlay
         trên body, element tại chỗ chỉ là chỗ neo; để trần sẽ thành flex-item ma ăn gap của .lp-split. -->
    <div class="dp-anchors">
    <!-- SIDE peek: drawer phải, KHÔNG mask (non-modal) → bảng/thẻ phía sau vẫn dùng được -->
    <nz-drawer
      [nzVisible]="open() && peekMode() === 'side'"
      [nzWidth]="sideW()"
      nzWrapClassName="dp-side-wrap"
      nzPlacement="right"
      [nzMask]="false"
      [nzClosable]="false"
      [nzTitle]="peekHead"
      [nzFooter]="footer() ?? null"
      (nzOnClose)="close()">
      <ng-container *nzDrawerContent>
        <!-- Tay kéo đổi độ rộng drawer (mép trái) — grip cho user nhận biết. -->
        <div class="dp-resize dp-resize--drawer" [class.dp-resizing]="resizing()" role="separator"
          aria-orientation="vertical" [attr.aria-label]="resizeLabel() || null"
          (pointerdown)="startResize($event, 'side')"><span class="dp-grip"></span></div>
        <ng-container [ngTemplateOutlet]="bodyTpl()" [ngTemplateOutletContext]="{ $implicit: peekMode() }" />
      </ng-container>
    </nz-drawer>

    <!-- CENTER peek: modal giữa màn hình — body cuộn (không vượt quá màn hình), hành động ở FOOTER
         (chuẩn modal design system). Truyền mode vào content để nội dung ẩn action bar nội bộ. -->
    <nz-modal
      [nzVisible]="open() && peekMode() === 'center'"
      nzCentered
      [nzWidth]="modalWidth()"
      [nzTitle]="peekHead"
      [nzClosable]="false"
      [nzBodyStyle]="{ 'max-height': '70vh', 'overflow-y': 'auto' }"
      [nzFooter]="footer() ?? null"
      (nzOnCancel)="close()">
      <ng-container *nzModalContent>
        <ng-container [ngTemplateOutlet]="bodyTpl()" [ngTemplateOutletContext]="{ $implicit: peekMode() }" />
      </ng-container>
    </nz-modal>
    </div>

    <!-- Header dùng chung (Notion-style): mở rộng · đổi mode · tiêu đề · đóng -->
    <ng-template #peekHead>
      <div class="pk-head">
        @if (expandable()) {
          <button type="button" class="pk-ic" [attr.aria-label]="expandLabel() || null"
            (click)="setMode('full')">
            <tabler-icon [icon]="icExpand" [size]="17" />
          </button>
          <span class="pk-sep"></span>
        }
        <button type="button" class="pk-ic" nz-dropdown [nzDropdownMenu]="modeMenu"
          nzTrigger="click" nzPlacement="bottomLeft" [attr.aria-label]="switchLabel() || null">
          <tabler-icon [icon]="icLayout" [size]="17" />
        </button>
        <span class="pk-title">{{ title() }}</span>
        <button type="button" class="pk-ic pk-close" [attr.aria-label]="closeLabel() || null" (click)="close()">
          <tabler-icon [icon]="icClose" [size]="17" />
        </button>
      </div>
    </ng-template>

    <nz-dropdown-menu #modeMenu="nzDropdownMenu">
      <ul nz-menu class="pk-menu">
        @for (m of modes(); track m) {
          <li nz-menu-item (click)="setMode(m)">
            <span class="pk-mi">
              <tabler-icon [icon]="$any(iconOf(m))" [size]="16" class="pk-mi-ic" />
              <span class="pk-mi-l">{{ labelOf(m) }}</span>
              @if (m === peekMode() && (m === 'master' || m === 'side' || m === 'center')) {
                <tabler-icon [icon]="icCheck" [size]="16" class="pk-mi-ck" />
              }
            </span>
          </li>
        }
      </ul>
    </nz-dropdown-menu>
  `,
  host: { class: 'hrm-detail-peek' },
  styles: [`
    /* Host trong suốt với layout: master aside trở thành con trực tiếp của hàng flex bên ngoài. */
    :host { display: contents; }
    /* Anchor drawer/modal không tham gia layout (overlay render trên body). */
    .dp-anchors { display: none; }

    /* MASTER — panel cố định bên phải: thẻ viền bo, header ghim, thân tự cuộn. */
    .dp-master {
      position: relative;
      flex: none; height: 100%; min-height: 0; display: flex; flex-direction: column;
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); overflow: hidden;
    }
    .dp-master.dp-resizing { user-select: none; }

    /* Tay kéo đổi độ rộng (mép trái panel/drawer) — dải mảnh + grip dọc; hover/kéo → highlight primary
       để user NHẬN BIẾT kéo được. Kéo sang trái = rộng ra (panel/drawer neo bên phải). */
    .dp-resize {
      position: absolute; left: 0; top: 0; bottom: 0; width: 12px; z-index: 4;
      display: flex; align-items: center; justify-content: center;
      cursor: col-resize; touch-action: none;
    }
    .dp-grip {
      width: 4px; height: 44px; border-radius: var(--radius-full);
      background: var(--border-strong, var(--border-sub));
      transition: background var(--duration-fast, .15s) var(--ease-out, ease),
                  height var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .dp-resize:hover .dp-grip, .dp-resizing .dp-grip { background: var(--primary-base); height: 60px; }
    /* Handle trong drawer: neo theo body drawer (đặt position relative để absolute bám đúng). */
    :host ::ng-deep .dp-side-wrap .ant-drawer-body { position: relative; }
    /* Vùng tiêu đề drawer chiếm TRỌN bề rộng → pk-head (width:100%) lấp đầy → nút đóng luôn mép PHẢI
       (một số bản ng-zorro không tự cho .ant-drawer-title flex:1). */
    :host ::ng-deep .dp-side-wrap .ant-drawer-header-title { flex: 1 1 auto; min-width: 0; }
    :host ::ng-deep .dp-side-wrap .ant-drawer-title { flex: 1 1 auto; min-width: 0; width: 100%; }
    .dp-resize--drawer { z-index: 20; }
    .dp-mhead { flex: none; padding: 8px 10px; border-bottom: 1px solid var(--border-soft); }
    .dp-mbody { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 16px; }
    /* FOOTER master — ghim đáy (fix cố định), viền trên, action dồn phải. Đồng bộ drawer/modal. */
    .dp-mfoot {
      flex: none; padding: 10px 16px; border-top: 1px solid var(--border-soft);
      background: var(--bg-surface); display: flex; align-items: center; justify-content: flex-end;
      gap: var(--space-2); flex-wrap: wrap;
    }

    /* Header full-width → nút đóng (pk-close) luôn nằm mép PHẢI (master · drawer · modal). */
    .pk-head { display: flex; align-items: center; gap: 2px; width: 100%; }
    .pk-ic {
      display: grid; place-items: center; width: 30px; height: 30px; flex: none;
      border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer;
      color: var(--icon-secondary);
    }
    .pk-ic:hover { background: var(--bg-surface-subtle); color: var(--icon-primary); }
    .pk-sep { width: 1px; height: 18px; background: var(--border-soft); margin: 0 4px; flex: none; }
    .pk-title {
      flex: 1; min-width: 0; margin-left: 6px; font-size: var(--fs-15); font-weight: 600;
      color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    .pk-close { margin-left: 4px; }
    .pk-mi { display: flex; align-items: center; gap: 10px; min-width: 168px; }
    .pk-mi-ic { color: var(--icon-secondary); flex: none; }
    .pk-mi-l { flex: 1; }
    .pk-mi-ck { color: var(--primary-base); flex: none; }
  `],
})
export class HrmDetailPeek {
  private readonly router = inject(Router);

  /** Đang mở chi tiết hay không. */
  readonly open = model(false);
  /** Surface hiện tại. Mặc định side (drawer). */
  readonly peekMode = model<HrmPeekMode>('side');
  /** Các mode cho phép chọn (mặc định đủ 4). */
  readonly modes = input<HrmPeekMode[]>(['side', 'center', 'full', 'tab']);
  /** Tiêu đề header. */
  readonly title = input('');
  /** Template nội dung chi tiết (bắt buộc để hiện). Nhận context $implicit = mode hiện tại. */
  readonly content = input<TemplateRef<unknown> | null>(null);
  /** Template FOOTER — dùng cho mode center (modal): cụm hành động ghim chân modal (chuẩn DS). */
  readonly footer = input<TemplateRef<unknown> | null>(null);
  /** Bề rộng drawer side peek. */
  readonly width = input(440);
  /** Bề rộng panel master (bảng trái · chi tiết phải). */
  readonly masterWidth = input(400);
  /** Bề rộng modal center peek. */
  readonly modalWidth = input(680);
  /** Route hiển thị bản ghi độc lập — dùng cho mode full (điều hướng) + tab (mở tab mới). */
  readonly routeUrl = input('');
  /** Nhãn i18n cho từng mode trong menu (bên gọi cấp — giữ i18n sạch). */
  readonly modeLabels = input<Partial<Record<HrmPeekMode, string>>>({});
  /** Nhãn a11y (i18n, bên gọi cấp). */
  readonly switchLabel = input('');
  readonly expandLabel = input('');
  /** Hiện nút ⤢ mở nhanh toàn trang ở header. Tắt khi dropdown đổi mode đã có "Toàn trang" (tránh trùng). */
  readonly expandable = input(true);
  readonly closeLabel = input('');
  /** Nhãn a11y cho tay kéo đổi độ rộng (i18n). */
  readonly resizeLabel = input('');

  /** Độ rộng do KÉO (ghi đè input; null = dùng input mặc định). Master + side riêng biệt. */
  private readonly masterWWrite = signal<number | null>(null);
  private readonly sideWWrite = signal<number | null>(null);
  protected readonly masterW = computed(() => this.masterWWrite() ?? this.masterWidth());
  protected readonly sideW = computed(() => this.sideWWrite() ?? this.width());
  /** Đang kéo — để highlight grip + chặn select. */
  protected readonly resizing = signal(false);

  /** Bắt đầu kéo: neo phải nên kéo sang TRÁI = rộng ra. Clamp [320, 760] (đơn giản, luôn kéo được). */
  protected startResize(e: PointerEvent, target: 'master' | 'side'): void {
    e.preventDefault();
    const startW = target === 'master' ? this.masterW() : this.sideW();
    const startX = e.clientX;
    this.resizing.set(true);
    const move = (ev: PointerEvent): void => {
      const nw = Math.max(320, Math.min(760, startW + (startX - ev.clientX)));
      if (target === 'master') this.masterWWrite.set(nw); else this.sideWWrite.set(nw);
    };
    const up = (): void => {
      document.removeEventListener('pointermove', move);
      document.removeEventListener('pointerup', up);
      this.resizing.set(false);
    };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  }

  protected readonly icExpand = IconArrowsDiagonal;
  protected readonly icLayout = IconLayout;
  protected readonly icClose = IconX;
  protected readonly icCheck = IconCheck;
  private readonly icons: Record<HrmPeekMode, unknown> = {
    master: IconLayoutColumns, side: IconLayoutSidebarRight, center: IconAppWindow,
    full: IconMaximize, tab: IconExternalLink,
  };

  /** Outlet an toàn: null → template rỗng (tránh outlet undefined). */
  protected readonly bodyTpl = computed<TemplateRef<unknown> | null>(() => this.content());

  protected iconOf(m: HrmPeekMode): unknown { return this.icons[m]; }
  protected labelOf(m: HrmPeekMode): string { return this.modeLabels()[m] ?? m; }

  protected close(): void { this.open.set(false); }

  /** Chọn mode: side/center render tại chỗ; full điều hướng route; tab mở tab browser mới. */
  protected setMode(m: HrmPeekMode): void {
    const url = this.routeUrl();
    if (m === 'full') {
      if (url) { this.router.navigateByUrl(url); this.open.set(false); }
      return;
    }
    if (m === 'tab') {
      if (url) window.open(url, '_blank', 'noopener');
      return;
    }
    this.peekMode.set(m);
  }
}
